   832→function generateSpeechTips(fillerRate, wpm, wordCount, totalFillers, fillerCounts) {
   833→  const tips = [];
   834→
   835→  if (fillerRate > 3) {
   836→    const topFillers = Object.entries(fillerCounts)
   837→      .sort((a, b) => b[1] - a[1])
