   976→  // Step 2: Run all analyses in parallel with PER-PROMISE timeouts
   977→  // BUG FIX (Feb 15, 2026): The old global timeout (Promise.race with 25s) was DESTRUCTIVE —
   978→  // when it fired, it replaced ALL results with rejections, including promises that had already
   979→  // completed successfully. E.g., vision analysis would succeed at 10s but get discarded at 25s
   980→  // because voice analysis was still running. Fix: wrap each promise individually with its own
   981→  // timeout, then use Promise.allSettled which preserves all settled results.
   982→  const PER_PROMISE_TIMEOUT_MS = 22000;
   983→
   984→  function withTimeout(promise, ms, label) {
   985→    return new Promise((resolve, reject) => {
   986→      const timer = setTimeout(() => {
   987→        console.warn(`[video-analysis] ${label} timed out after ${ms}ms`);
   988→        reject(new Error(`${label} timeout after ${ms}ms`));
   989→      }, ms);
   990→      promise.then(
   991→        val => { clearTimeout(timer); resolve(val); },
   992→        err => { clearTimeout(timer); reject(err); }
   993→      );
   994→    });
   995→  }
   996→
   997→  // FIX (Feb 15, 2026): Pass transcription context to video presentation analysis
   998→  // so the text-based LLM can generate personalized coaching from speech patterns
   999→  const presentationOptions = {
  1000→    ...options,
  1001→    transcription: finalTranscription,
  1002→    durationSeconds,
  1003→    question,
  1004→  };
  1005→
  1006→  const analysisPromises = [
  1007→    withTimeout(analyzeInterviewResponse(question, finalTranscription, keyPoints, options), PER_PROMISE_TIMEOUT_MS, 'contentAnalysis'),
  1008→    withTimeout(generateInterviewCoaching(question, finalTranscription, { score: 5, strengths: [], improvements: [] }, options), PER_PROMISE_TIMEOUT_MS, 'contentCoaching'),
  1009→    withTimeout(analyzeVideoPresentation(frames, presentationOptions), PER_PROMISE_TIMEOUT_MS, 'videoPresentation'),
