  1014→    withTimeout(analyzeVoiceQuality(finalTranscription, durationSeconds, options), PER_PROMISE_TIMEOUT_MS, 'voiceAnalysis')
  1015→  ];
  1016→
  1017→  // Promise.allSettled waits for ALL promises to settle — each has its own timeout so
  1018→  // successful results are never discarded by a slow sibling promise
  1019→  let settled;
  1020→  try {
  1021→    settled = await Promise.allSettled(analysisPromises);
  1022→  } catch (err) {
  1023→    console.error('[video-analysis] Promise.allSettled unexpected error:', err.message);
