  1026→
  1027→  // Extract results with fallbacks for any failed analyses
  1028→  // BUG FIX: Use helper function with multiple safety layers to prevent null crashes.
  1029→  // Previous null checks still let through edge cases where AI returned non-null truthy values
  1030→  // that were missing expected fields, causing TypeError: Cannot read properties of null.
  1031→  function safeExtract(index, fallback) {
  1032→    try {
  1033→      const s = settled[index];
  1034→      if (s && s.status === 'fulfilled' && s.value != null && typeof s.value === 'object') {
  1035→        return s.value;
