  1227→// AI interviewer conducts a conversational interview turn
  1228→async function conductInterviewTurn(conversation, baseQuestions, currentQuestionIndex, targetRole, options = {}) {
  1229→  // Send last 12 turns for better context on follow-ups
  1230→  const recentConvo = conversation.slice(-12);
  1231→  const convoText = recentConvo.map(turn => {
  1232→    if (turn.role === 'interviewer') return `INTERVIEWER: ${turn.text}`;
  1233→    return `CANDIDATE: ${turn.text}`;
  1234→  }).join('\n\n');
  1235→
  1236→  const candidateTurnCount = conversation.filter(t => t.role === 'candidate').length;
  1237→  const followUpCount = conversation.filter(t => t.role === 'interviewer' && (t.action === 'follow_up' || t.action === 'challenge')).length;
  1238→  const remainingQuestions = baseQuestions.slice(currentQuestionIndex);
  1239→  const nextPlannedQuestion = remainingQuestions.length > 0
  1240→    ? remainingQuestions[0].question_text
  1241→    : null;
  1242→
  1243→  // Count consecutive follow-ups on the current topic
  1244→  let consecutiveFollowUps = 0;
  1245→  for (let i = conversation.length - 1; i >= 0; i--) {
  1246→    const t = conversation[i];
  1247→    if (t.role === 'interviewer' && (t.action === 'follow_up' || t.action === 'challenge')) {
  1248→      consecutiveFollowUps++;
  1249→    } else if (t.role === 'interviewer' && t.action === 'transition') {
  1250→      break;
  1251→    } else if (t.role === 'candidate') {
  1252→      continue; // skip candidate turns when counting
  1253→    }
  1254→  }
  1255→
  1256→  const prompt = `You are conducting a mock interview for a "${targetRole}" position. You have ${remainingQuestions.length} planned questions remaining.
  1257→
  1258→CONVERSATION SO FAR:
  1259→${convoText}
  1260→
  1261→${nextPlannedQuestion ? `NEXT PLANNED QUESTION (use when ready to move on): "${nextPlannedQuestion}"` : 'All planned questions covered.'}
  1262→
  1263→FOLLOW-UP COUNT on current topic: ${consecutiveFollowUps}
  1264→
  1265→YOUR TASK: Act like a real interviewer. After the candidate answers:
  1266→
  1267→1. **FOLLOW UP** if the answer is:
  1268→   - Vague or surface-level ("I worked on a project" → ask WHAT project, what was the challenge)
  1269→   - Missing specifics (no metrics, no concrete examples, no details about their role)
  1270→   - Interesting but unexplored (they mentioned something worth digging into)
  1271→   - Missing the "so what" (they described what happened but not the impact/result)
  1272→   You can ask MULTIPLE follow-ups on the same topic. Keep probing until you have real depth.
  1273→
  1274→2. **TRANSITION** to the next planned question when:
  1275→   - The candidate gave a thorough, specific answer with concrete examples
  1276→   - You've already asked 2-3 follow-ups and have sufficient depth
  1277→   - The candidate clearly has nothing more to add on this topic
  1278→
  1279→3. **WRAP UP** when: ${candidateTurnCount >= 6 ? 'You feel you have enough data (6+ exchanges completed)' : 'NOT YET — keep interviewing, only ' + candidateTurnCount + ' exchanges so far'}
  1280→
  1281→React to their answer specifically (1-2 sentences — reference something concrete they said, NOT generic filler like "Thank you for that response" or "That's helpful"). Show you actually listened. Example good reactions: "That 40% improvement in pipeline throughput is impressive — how did you measure that?" or "Interesting that you chose to refactor first rather than ship the feature." Example bad reactions: "Thank you for sharing that." or "That's great, thanks."
  1282→
  1283→Return JSON: {"reaction":"1-2 sentences referencing SPECIFIC details from their answer","action":"follow_up|challenge|transition|wrap_up","question":"your next question","score_hint":1-10,"notes":"brief note on answer quality"}`;
  1284→
  1285→  const result = await chat(prompt, {
  1286→    system: `You are Alex, an experienced ${targetRole} interviewer. You conduct interviews like a real person — curious, attentive, and thorough. You don't just read from a script. When a candidate gives a vague answer, you probe deeper. When they mention something interesting, you explore it. You ask follow-up questions naturally, like "Tell me more about that" or "What specifically was your role in that?" or "How did you measure success?" You only move to the next planned question when you're genuinely satisfied with the depth of their answer. Always return valid JSON only.`,
  1287→    maxTokens: 1024,
  1288→    subscriptionId: options.subscriptionId,
  1289→    module: 'mock_interview', feature: 'interview_turn'
  1290→  });
  1291→
  1292→  const parsed = safeParseJSON(result);
  1293→  if (parsed) return parsed;
  1294→  throw new Error('Failed to generate interview turn — could not parse LLM response');
  1295→}
