  1297→// Generate session-end feedback for a mock interview
  1298→// Returns structured format matching practice interview: content + communication + presentation
  1299→async function generateSessionFeedback(conversation, targetRole, options = {}) {
  1300→  const convoText = conversation.map(turn => {
  1301→    if (turn.role === 'interviewer') return `INTERVIEWER: ${turn.text}`;
  1302→    return `CANDIDATE: ${turn.text}`;
  1303→  }).join('\n\n');
  1304→
  1305→  // Calculate basic metrics from the text
  1306→  const candidateTurns = conversation.filter(t => t.role === 'candidate');
  1307→  const allCandidateText = candidateTurns.map(t => t.text).join(' ');
  1308→  const wordCount = allCandidateText.split(/\s+/).filter(w => w).length;
  1309→  const questionCount = conversation.filter(t => t.role === 'interviewer').length;
  1310→
  1311→  // Estimate duration from timestamps
  1312→  let durationSeconds = 0;
  1313→  if (conversation.length >= 2) {
  1314→    const first = new Date(conversation[0].timestamp || Date.now());
  1315→    const last = new Date(conversation[conversation.length - 1].timestamp || Date.now());
  1316→    durationSeconds = Math.max(60, Math.round((last - first) / 1000));
  1317→  }
  1318→  const wpm = durationSeconds > 0 ? Math.round(wordCount / (durationSeconds / 60)) : 120;
  1319→
  1320→  const prompt = `You just completed a mock interview for a "${targetRole}" position. Review the full conversation and provide structured feedback in THREE sections matching our coaching format.
  1321→
  1322→FULL INTERVIEW TRANSCRIPT:
  1323→${convoText}
  1324→
  1325→SPEECH METRICS (from recording):
  1326→- Total words: ${wordCount}
  1327→- Questions answered: ${candidateTurns.length}
  1328→- Estimated duration: ${Math.round(durationSeconds / 60)} minutes
  1329→- Estimated WPM: ${wpm}
  1330→
  1331→Analyze the entire interview and return a JSON object with this EXACT structure:
  1332→
  1333→{
  1334→  "overall_score": 1-10,
  1335→  "interview_readiness": "ready|almost_ready|needs_work",
  1336→  "summary": "3-4 sentence overall assessment referencing specific answers",
  1337→
  1338→  "content": {
  1339→    "score": 1-10,
  1340→    "strengths": ["Specific strength with example from their answers — quote them", "Another strength"],
  1341→    "improvements": ["Specific improvement area with example", "Another improvement"],
  1342→    "covered_points": ["Key competency they demonstrated well"],
  1343→    "missed_points": ["Important area they didn't address or was weak"],
  1344→    "detailed_feedback": "2-3 paragraph deep analysis of their answer quality across ALL questions. Reference patterns: did they improve? Were some topics stronger? Did follow-ups reveal depth or gaps?",
  1345→    "specific_tips": ["Actionable tip 1", "Actionable tip 2", "Actionable tip 3"],
