  tts_magpie_zeroshot: 'nvidia/magpie-tts-zeroshot',          // English voice cloning (requires audio prompt, restricted access)
  tts_fastpitch: 'nvidia/fastpitch-hifigan-tts',              // Basic English TTS (lightweight)

